/****************************************************************************
 * contest2026_135_yongwangzhiqian/board/bk7258/src/bk7258_bringup.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Application-facing device and filesystem bringup for the Beken BK7258.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/mount.h>
#include <sys/stat.h>

#include <debug.h>

#ifdef CONFIG_BK7258_FLASH_MTD
#  include <nuttx/fs/fs.h>
#  include <nuttx/mtd/mtd.h>
#  include "bk7258_flash_mtd.h"
#endif

#ifdef CONFIG_BK7258_FLASH_LITTLEFS
#  include <nuttx/fs/fs.h>
#endif

#if defined(CONFIG_FS_PROCFS) && defined(CONFIG_BK7258_DVFS_PROCFS)
#  include "bk7258_dvfs.h"
#endif

#include "bk7258_internal.h"

/****************************************************************************
 * Private Data and Functions
 ****************************************************************************/

#ifdef CONFIG_BK7258_FLASH_LITTLEFS
/* LittleFS bring-up: register /dev/mtdblock0 (FTL) and mount /data.  Storage
 * validation belongs to an explicitly selected application/test; normal
 * board bring-up must not create or rewrite a probe file on every boot.
 */

#define BK7258_FS_MOUNTPOINT  "/data"
#define BK7258_FS_BLOCKDEV    "/dev/mtdblock0"
static void bk7258_fs_mount(struct mtd_dev_s *mtd)
{
  if (ftl_initialize(0, mtd) < 0)
    {
      _err("bk7258: failed to register LittleFS FTL block device\n");
      return;
    }

  mkdir(BK7258_FS_MOUNTPOINT, 0777);

  if (mount(BK7258_FS_BLOCKDEV, BK7258_FS_MOUNTPOINT, "littlefs", 0,
            "autoformat") < 0)
    {
      _err("bk7258: failed to mount LittleFS at %s\n",
           BK7258_FS_MOUNTPOINT);
      return;
    }
}
#endif /* CONFIG_BK7258_FLASH_LITTLEFS */

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_bringup
 *
 * Description:
 *   Ensure mandatory platform initialization has completed, then register
 *   application-facing procfs, MTD and filesystem services.
 ****************************************************************************/

int bk7258_bringup(void)
{
  int ret;

  ret = bk7258_platform_initialize();
  if (ret < 0)
    {
      return ret;
    }

  /* Register the BK7258 DVFS /proc/dvfs entry *before* mounting procfs: the
   * fs_procfs NOTE requires the procfs entry table to be stable at mount
   * time (procfs_register reallocs the table; doing it after the mount would
   * race with concurrent procfs access).
   */

#if defined(CONFIG_FS_PROCFS) && defined(CONFIG_BK7258_DVFS_PROCFS)
  (void)bk7258_dvfs_procfs_register();
#endif

  /* Mount procfs at the NSH proc mountpoint so ps, ls /proc, and cat of
   * /proc entries work.  CONFIG_NSH_ARCHINIT activates this hook;
   * CONFIG_FS_PROCFS provides the filesystem.
   */

#if defined(CONFIG_FS_PROCFS) && defined(CONFIG_NSH_PROC_MOUNTPOINT)
  (void)mount(NULL, CONFIG_NSH_PROC_MOUNTPOINT, "procfs", 0, NULL);
#endif

#ifdef CONFIG_BK7258_FLASH_MTD
  /* Create the MTD instance for the 1 MiB data partition.  When LittleFS is
   * also enabled, register /dev/mtdblock0 and mount /data on the same
   * instance.
   */

  FAR struct mtd_dev_s *mtd = bk7258_flash_mtd_initialize();
  if (mtd != NULL)
    {
#ifdef CONFIG_BK7258_FLASH_LITTLEFS
      bk7258_fs_mount(mtd);
#endif
#ifdef CONFIG_MCUBOOT_BOOTLOADER
      /* Publish read-only, bounds-checked image-pair partitions only to the
       * NuttX MCUboot BL2 profile.
       */

      if (register_mtddriver(
            CONFIG_MCUBOOT_PRIMARY_SLOT_PATH,
            bk7258_mcuboot_mtd_get(BK7258_MCUBOOT_MTD_SLOT_PRIMARY),
            0600, NULL) < 0 ||
          register_mtddriver(
            CONFIG_MCUBOOT_SECONDARY_SLOT_PATH,
            bk7258_mcuboot_mtd_get(BK7258_MCUBOOT_MTD_SLOT_SECONDARY),
            0600, NULL) < 0)
        {
          _err("bk7258: MCUboot MTD node registration failed\n");
        }
#endif
    }
#endif

  return 0;
}

/****************************************************************************
 * contest2026_135_yongwangzhiqian/board/bk7258/scripts/ld.script
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Linker script for the Beken BK7258 (T5-AI, Cortex-M33) CPU0/CP image.
 *
 * ADR-004 aligns the executable pair with the official v3.1.1.9 A/B layout:
 *
 *   FLASH : 0x02010000 .. 0x0214ffff  (CP logical offset 0x10000,
 *                                      0x140000 bytes)
 *   AP SMP spinlocks: 0x28000000 .. 0x2800ffff (official reserved region)
 *   RAM   : 0x28010000 .. 0x2804ffff  (256 KiB CP-owned SRAM)
 *   MSP   : 0x2804fffc
 *
 * The AP image follows contiguously at logical 0x00150000 / XIP 0x02150000.
 * LittleFS is raw-only at 0x00600000..0x006fffff.  AP RAM starts at
 * 0x28050000 and the top 4 KiB page at 0x2809f000 is shared boot-state.
 *
 * The .vectors section (80 entries, 0x140 bytes from bk7258_vectors.c) is
 * KEEP-pinned first so that:
 *   - file offset 0x000 == slot [0] == initial MSP (0x2809FFFC)
 *   - file offset 0x004 == slot [1] == __start (Thumb entry)
 *   - file offset 0x100 == slot [64] == app magic "BK72"
 *   - file offset 0x104 == slot [65] == app magic "36\0\0"
 *   - file offset 0x108 == slot [66] == first upper external IRQ
 *   - file offset 0x13c == slot [79] == last upper external IRQ
 ****************************************************************************/

/* The linker script is preprocessed to .tmp before being passed to ld;
 * include the build config so CONFIG_ARCH_INTERRUPTSTACK (used in
 * .irq_stack below) and any other CONFIG_* values are substituted.
 */

#include <nuttx/config.h>
#include "../chip/include/bk7258_memorymap.h"
#include <bk7258_partition_layout.h>

OUTPUT_ARCH("arm")
EXTERN(_vectors)

/* Keep the architecture's TCB/register description in the final ELF.  It is
 * consumed by the official J-Link RTOS plugin out-of-band, so no target-side
 * reference would otherwise extract arm_tcbinfo.o from libarch.a. */

#ifdef CONFIG_ARCH_HAVE_TCBINFO
EXTERN(g_tcbinfo)
#endif

#ifdef CONFIG_BK7258_SDK_IRQ_BRIDGE
/* Force the overlay bridge member out of libarch.a before the Beken SDK
 * archives are scanned.  Otherwise libdriver.a(interrupt_base.c.obj) can
 * satisfy the first timer-driver reference and retain the private CM33
 * callback table.
 */

EXTERN(bk_int_isr_register)
#endif

ENTRY(_vectors)

/* A MCUboot payload stores its header before the Cortex-M vector table.
 * Normal BL1-direct images retain the historical origin unchanged.
 */

#ifdef CONFIG_BK7258_BL2_IMAGE
#  define BK7258_CP_IMAGE_HEADER_SIZE 0
#  define BK7258_CP_IMAGE_FLASH_BASE 0x28020000
#  define BK7258_CP_IMAGE_FLASH_SIZE BK7258_ROLE_BL2_LOGICAL_SIZE
#  define BK7258_CP_IMAGE_RAM_BASE   0x28010000
#  define BK7258_CP_IMAGE_RAM_SIZE   0x00010000
#elif defined(CONFIG_BK7258_MCUBOOT_IMAGE)
#  /* The Cortex-M VTOR masks its low bits according to the vector-table
#   * size.  This board has 80 entries, so the table needs 0x200-byte
#   * alignment.  Keep the entire MCUboot header in that alignment gap. */
#  define BK7258_CP_IMAGE_HEADER_SIZE 0x200
#  define BK7258_CP_IMAGE_FLASH_BASE BK7258_ROLE_SLOT_A_CP_XIP_START
#  define BK7258_CP_IMAGE_FLASH_SIZE BK7258_ROLE_SLOT_A_CP_LOGICAL_SIZE
#else
#  define BK7258_CP_IMAGE_HEADER_SIZE 0
#  define BK7258_CP_IMAGE_FLASH_BASE BK7258_ROLE_SLOT_A_CP_XIP_START
#  define BK7258_CP_IMAGE_FLASH_SIZE BK7258_ROLE_SLOT_A_CP_LOGICAL_SIZE
#endif

#ifndef BK7258_CP_IMAGE_RAM_BASE
#  define BK7258_CP_IMAGE_RAM_BASE   0x28010000
#  define BK7258_CP_IMAGE_RAM_SIZE   0x040000
#endif

#define BK7258_CP_IMAGE_FLASH_ORIGIN \
  (BK7258_CP_IMAGE_FLASH_BASE + BK7258_CP_IMAGE_HEADER_SIZE)
#define BK7258_CP_IMAGE_FLASH_LENGTH \
  (BK7258_CP_IMAGE_FLASH_SIZE - BK7258_CP_IMAGE_HEADER_SIZE)

MEMORY
{
    FLASH (rx)  : ORIGIN = BK7258_CP_IMAGE_FLASH_ORIGIN,
                  LENGTH = BK7258_CP_IMAGE_FLASH_LENGTH
    RAM   (rwx) : ORIGIN = BK7258_CP_IMAGE_RAM_BASE,
                  LENGTH = BK7258_CP_IMAGE_RAM_SIZE
}

/* N9 shared-memory ABI is outside CP RAM.  Export the same absolute symbols
 * from both images so the post-link verifier can reject any drift.
 */

_bk7258_rptun_shmem_start = 0x28097000;
_bk7258_rptun_shmem_end = 0x2809f000;
_bk7258_rptun_control = 0x28097000;
_bk7258_rptun_resource = 0x28097040;
_bk7258_rptun_carveout_start = 0x28097180;
_bk7258_rptun_carveout_end = 0x2809f000;

/* The CPU0 BL2 profile reserves SRAM1 for data/stack and 0x28020000 onward for
 * copied executable text.  Ordinary CP profiles retain their original RAM.
 */

_estack = ORIGIN(RAM) + LENGTH(RAM) - 4;

SECTIONS
{
    /* Vector table FIRST, pinned at the image execution address or immediately
     * after the MCUboot payload header.  KEEP() prevents the
     * linker from GC'ing it; . = ORIGIN(FLASH) pins the address.
     */
    . = ORIGIN(FLASH);
    .vectors : ALIGN(4)
    {
        KEEP(*(.vectors))
        . = ALIGN(4);
    } > FLASH

    /* Permanent A1 linker gates for .vectors section.
     * _vectors must be pinned at flash origin; size must be 0x140 (80 slots).
     */

    ASSERT(_vectors == ORIGIN(FLASH),
           "ERROR: _vectors must be at generated CP FLASH origin (A1 gate)")
    ASSERT(SIZEOF(.vectors) == 0x140,
           "ERROR: .vectors must be 0x140 bytes (80 entries, A1 gate)")

    /* Code + read-only data.  BL2 stores these bytes in flash but executes
     * them from RAM after BL1's complete logical-image copy. */
    .text : ALIGN(4)
    {
        _stext = ABSOLUTE(.);
        *(.text .text.*)
        *(.fixup)
        *(.gnu.warning)
        *(.rodata .rodata.*)
        *(.gnu.linkonce.t.*)
        *(.glue_7)
        *(.glue_7t)
        *(.gcc_except_table)
        *(.gnu.linkonce.r.*)
        KEEP(*(.psram_boot_text))
        . = ALIGN(4);
        _etext = ABSOLUTE(.);
    } > FLASH

    /* Constructors / destructors (NuttX init_section convention). */
    .init_section : ALIGN(4)
    {
        _sinit = ABSOLUTE(.);
        KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*) SORT_BY_INIT_PRIORITY(.ctors.*)))
        KEEP(*(.init_array EXCLUDE_FILE(*crtbegin.o *crtbegin?.o *crtend.o *crtend?.o) .ctors))
        _einit = ABSOLUTE(.);
    } > FLASH

    /* ARM exception unwinding tables -- keep them out of the way. */
    .ARM.extab : ALIGN(4)
    {
        *(.ARM.extab*)
    } > FLASH

    .ARM.exidx : ALIGN(4)
    {
        __exidx_start = ABSOLUTE(.);
        *(.ARM.exidx*)
        __exidx_end = ABSOLUTE(.);
    } > FLASH

    /* SDK bk_api_ipc channel table.  The entries live in the immutable SDK
     * libraries and the section name is not a valid C identifier, so the
     * linker needs explicit KEEP plus PROVIDE_HIDDEN boundary symbols or
     * --gc-sections discards the table and bk_ipc_init() finds nothing.
     */

    .ipc_chan_reg : ALIGN(4)
    {
        PROVIDE_HIDDEN(__start_ipc_chan_reg = .);
        KEEP(*(.ipc_chan_reg))
        PROVIDE_HIDDEN(__stop_ipc_chan_reg = .);
    } > FLASH

    /* Thread-local storage (NuttX ARM convention). */
    .tdata : ALIGN(4)
    {
        _stdata = ABSOLUTE(.);
        *(.tdata .tdata.* .gnu.linkonce.td.*);
        _etdata = ABSOLUTE(.);
    } > FLASH

    .tbss : ALIGN(4)
    {
        _stbss = ABSOLUTE(.);
        *(.tbss .tbss.* .gnu.linkonce.tb.* .tcommon);
        _etbss = ABSOLUTE(.);
    } > FLASH

    /* Load address of .data (LMA right after the last flash-resident
     * section).  Reset code copies from _eronly to _sdata.._edata.
     */
    _eronly = LOADADDR(.data);

    /* Interrupt stack in RAM (NuttX arm_getintstack.c references
     * g_intstackalloc / g_intstacktop).  Placed at the very start of RAM
     * so it has a fixed, predictable location.
     */
    .irq_stack : ALIGN(4)
    {
        g_intstackalloc = ABSOLUTE(.);
        . += CONFIG_ARCH_INTERRUPTSTACK;
        g_intstacktop = ABSOLUTE(.);
    } > RAM

    .ram_vectors (NOLOAD) : ALIGN(512)
    {
        _sram_vectors = ABSOLUTE(.);
        KEEP(*(.ram_vectors))
        . = ALIGN(4);
        _eram_vectors = ABSOLUTE(.);
    } > RAM

    ASSERT((_sram_vectors & 0x1ff) == 0,
           "ERROR: .ram_vectors must be 512-byte aligned")

    /* Permanent A1 gate: .ram_vectors must be 0x140 bytes (80 slots x 4).
     */

    ASSERT(_eram_vectors - _sram_vectors == 0x140,
           "ERROR: .ram_vectors must be 0x140 bytes (80 entries, A1 gate)")

    /* Initialized data: VMA in RAM, LMA in FLASH right after .tbss/.ARM. */
    .data : ALIGN(4)
    {
        _sdata = ABSOLUTE(.);
        *(.data .data.*)
        *(.gnu.linkonce.d.*)
#ifdef CONFIG_BK7258_RPTUN_LAYOUT
        /* Explicitly consume vendor ABI sections that GNU ld would otherwise
         * emit as orphan output sections outside the _sdata.._edata copy.
         */

        *(.swap_data)
        *(.dtcm_sec_data)
#endif
        CONSTRUCTORS
        . = ALIGN(4);
        _edata = ABSOLUTE(.);
    } > RAM AT > FLASH

    /* Zero-initialized data. */
    .bss (NOLOAD) : ALIGN(4)
    {
        _sbss = ABSOLUTE(.);
        *(.bss .bss.*)
        *(.gnu.linkonce.b.*)
#ifdef CONFIG_BK7258_RPTUN_LAYOUT
        *(.sram_spinlock_section)
#endif
        *(COMMON)
        /* The reset vector's initial MSP is _ebss + IDLE stack size; AAPCS
         * and the MCUboot packer both want it 8-byte aligned. */
        . = ALIGN(8);
        _ebss = ABSOLUTE(.);
    } > RAM

    /* Heap: from end of BSS up to the MSP region.  N1 never uses it but
     * the symbols must exist for the common ARM code to link.
     */
    . = ALIGN(16);
    _sheap = ABSOLUTE(.);
#ifdef CONFIG_BK7258_SWD_DEBUG
    /* Preserve the last 2 KiB of CP SRAM across warm reset.  The diagnostic
     * trace is addressed explicitly at 0x2804f800, remains outside BL2's
     * 0x28010000..0x2802ffff copy window, and is never handed to the heap. */
    _eheap = 0x2804f7fc;
    ASSERT(_ebss + CONFIG_IDLETHREAD_STACKSIZE <= 0x2804f7fc,
           "ERROR: CP image/IDLE stack overlaps SWD trace")
#else
    _eheap = ORIGIN(RAM) + LENGTH(RAM) - 4;
#endif

    ASSERT(LOADADDR(.data) + SIZEOF(.data) <=
           ORIGIN(FLASH) + LENGTH(FLASH),
           "ERROR: CP image exceeds official primary_cp_app")
    ASSERT(_eheap < BK7258_CP_IMAGE_RAM_BASE + BK7258_CP_IMAGE_RAM_SIZE,
           "ERROR: image RAM exceeds its reserved window")
    ASSERT(ORIGIN(RAM) == 0x28010000,
           "ERROR: CP RAM overlaps the official AP spinlock region")
#ifdef CONFIG_BK7258_RPTUN_LAYOUT
    ASSERT(_bk7258_rptun_shmem_start >= 0x28050000,
           "ERROR: RPTUN shared memory overlaps CP RAM")
    ASSERT(_bk7258_rptun_shmem_end == 0x2809f000,
           "ERROR: RPTUN shared memory overlaps telemetry")
    ASSERT(_bk7258_rptun_carveout_start == 0x28097180,
           "ERROR: RPTUN carveout ABI drift")
#endif

    /* Stabs / debug sections -- discard nothing but keep them at VMA 0 so
     * they don't perturb the runtime image.
     */
    .stab              0 : { *(.stab) }
    .stabstr           0 : { *(.stabstr) }
    .stab.excl         0 : { *(.stab.excl) }
    .stab.exclstr      0 : { *(.stab.exclstr) }
    .stab.index        0 : { *(.stab.index) }
    .stab.indexstr     0 : { *(.stab.indexstr) }
    .comment           0 : { *(.comment) }
    .debug_abbrev      0 : { *(.debug_abbrev) }
    .debug_info        0 : { *(.debug_info) }
    .debug_line        0 : { *(.debug_line) }
    .debug_pubnames    0 : { *(.debug_pubnames) }
    .debug_aranges     0 : { *(.debug_aranges) }
}

/****************************************************************************
 * contest2026_135_yongwangzhiqian/board/bk7258/chip/common/
 * bk7258_serial.c
 *
 * SPDX-License-Identifier: Apache-2.0
 *
 * Configurable SDK-backed UART0/UART1/UART2 NuttX serial lower halves.
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/ioctl.h>
#include <sys/types.h>
#include <stdbool.h>
#include <stdint.h>
#include <errno.h>
#include <termios.h>

#include <nuttx/fs/fs.h>
#include <nuttx/serial/serial.h>

#include <driver/gpio.h>
#include <driver/uart.h>
#include <driver/uart_types.h>

#include "arm_internal.h"
#include <arch/chip/bk7258_console.h>

#if defined(CONFIG_BK7258_UART0) || defined(CONFIG_BK7258_UART1) || \
    defined(CONFIG_BK7258_UART2)
#  define BK7258_HAVE_UART_DEVICE 1
#endif

#ifdef BK7258_HAVE_UART_DEVICE

#define BK7258_UART0_FLOW_THRESHOLD 127u

/* v3.1.1.9 exports these GPIO mapper entry points but omits their public
 * prototypes from the packaged wrapper header.
 */

extern bk_err_t gpio_dev_unmap(gpio_id_t gpio_id);
extern bk_err_t gpio_dev_map(gpio_id_t gpio_id, gpio_dev_t dev);

struct bk7258_uart_s
{
  uart_id_t id;
  uint32_t baud;
  uint8_t data_bits;
  uint8_t parity;
  uint8_t stop_bits;
  bool flow_control;
  bool initialized;
  bool rx_enabled;
  int rxbyte;
};

static const struct uart_ops_s g_bk7258_uart_ops;
static bool g_bk7258_uart_driver_initialized;

#define BK7258_DECLARE_UART(n, uartid, initial_baud, initial_bits, \
                            initial_parity, initial_stop, initial_flow) \
  static struct bk7258_uart_s g_bk7258_uart##n##priv = \
  { \
    .id = uartid, \
    .baud = initial_baud, \
    .data_bits = initial_bits, \
    .parity = initial_parity, \
    .stop_bits = initial_stop, \
    .flow_control = initial_flow, \
    .rxbyte = -1, \
  }; \
  static char g_bk7258_uart##n##rx[CONFIG_BK7258_UART_RXBUFSIZE]; \
  static char g_bk7258_uart##n##tx[CONFIG_BK7258_UART_TXBUFSIZE]; \
  static struct uart_dev_s g_bk7258_uart##n##dev = \
  { \
    .ops = &g_bk7258_uart_ops, \
    .priv = &g_bk7258_uart##n##priv, \
    .recv = \
      { \
        .size = CONFIG_BK7258_UART_RXBUFSIZE, \
        .buffer = g_bk7258_uart##n##rx, \
      }, \
    .xmit = \
      { \
        .size = CONFIG_BK7258_UART_TXBUFSIZE, \
        .buffer = g_bk7258_uart##n##tx, \
      }, \
  }

#ifdef CONFIG_BK7258_UART0
#  ifdef CONFIG_BK7258_UART0_FLOW_CONTROL
#    define BK7258_UART0_INITIAL_FLOW true
#  else
#    define BK7258_UART0_INITIAL_FLOW false
#  endif
BK7258_DECLARE_UART(0, UART_ID_0, CONFIG_BK7258_UART0_BAUD,
                    CONFIG_BK7258_UART0_DATA_BITS,
                    CONFIG_BK7258_UART0_PARITY,
                    CONFIG_BK7258_UART0_STOP_BITS,
                    BK7258_UART0_INITIAL_FLOW);
#endif

#ifdef CONFIG_BK7258_UART1
BK7258_DECLARE_UART(1, UART_ID_1, CONFIG_BK7258_UART1_BAUD,
                    CONFIG_BK7258_UART1_DATA_BITS,
                    CONFIG_BK7258_UART1_PARITY,
                    CONFIG_BK7258_UART1_STOP_BITS, false);
#endif

#ifdef CONFIG_BK7258_UART2
BK7258_DECLARE_UART(2, UART_ID_2, CONFIG_BK7258_UART2_BAUD,
                    CONFIG_BK7258_UART2_DATA_BITS,
                    CONFIG_BK7258_UART2_PARITY,
                    CONFIG_BK7258_UART2_STOP_BITS, false);
#endif

#if defined(CONFIG_BK7258_CONSOLE_UART0)
#  define CONSOLE_DEV g_bk7258_uart0dev
#elif defined(CONFIG_BK7258_CONSOLE_UART1)
#  define CONSOLE_DEV g_bk7258_uart1dev
#elif defined(CONFIG_BK7258_CONSOLE_UART2)
#  define CONSOLE_DEV g_bk7258_uart2dev
#endif

static bool bk7258_uart_is_console(struct uart_dev_s *dev)
{
#ifdef BK7258_HAVE_UART_CONSOLE
  return dev == &CONSOLE_DEV;
#else
  (void)dev;
  return false;
#endif
}

static uart_data_bits_t bk7258_uart_data_bits(uint8_t bits)
{
  return (uart_data_bits_t)(bits - 5u);
}

static uart_parity_t bk7258_uart_parity(uint8_t parity)
{
  return (uart_parity_t)parity;
}

static uart_stop_bits_t bk7258_uart_stop_bits(uint8_t stop_bits)
{
  return stop_bits == 2u ? UART_STOP_BITS_2 : UART_STOP_BITS_1;
}

static int bk7258_uart_driver_initialize(void)
{
  if (g_bk7258_uart_driver_initialized)
    {
      return OK;
    }

  if (bk_gpio_driver_init() != BK_OK || bk_uart_driver_init() != BK_OK)
    {
      return -EIO;
    }

  g_bk7258_uart_driver_initialized = true;
  return OK;
}

static int bk7258_uart_apply_pin_route(struct bk7258_uart_s *priv)
{
#ifdef CONFIG_BK7258_UART0_FLOW_CONTROL
  if (priv->id == UART_ID_0 &&
      (gpio_dev_unmap(GPIO_12) != BK_OK ||
       gpio_dev_unmap(GPIO_13) != BK_OK ||
       gpio_dev_map(GPIO_12, GPIO_DEV_UART0_RTS) != BK_OK ||
       gpio_dev_map(GPIO_13, GPIO_DEV_UART0_CTS) != BK_OK ||
       bk_gpio_pull_down(GPIO_12) != BK_OK ||
       bk_gpio_pull_down(GPIO_13) != BK_OK))
    {
      return -EIO;
    }
#endif

#if defined(CONFIG_BK7258_UART2) && \
    defined(CONFIG_BK7258_UART2_PINS_P40_P41)
  if (priv->id == UART_ID_2)
    {
      /* bk_uart_init() establishes the official P31/P30 default first.
       * Move ownership atomically to the alternate P41/P40 chip mux and do
       * not leave duplicate UART2 outputs active.
       */

      if (gpio_dev_unmap(GPIO_31) != BK_OK ||
          gpio_dev_unmap(GPIO_30) != BK_OK ||
          gpio_dev_unmap(GPIO_41) != BK_OK ||
          gpio_dev_unmap(GPIO_40) != BK_OK ||
          gpio_dev_map(GPIO_41, GPIO_DEV_UART2_TXD) != BK_OK ||
          gpio_dev_map(GPIO_40, GPIO_DEV_UART2_RXD) != BK_OK)
        {
          return -EIO;
        }
    }
#else
  (void)priv;
#endif

  return OK;
}

static int bk7258_uart_apply_format(struct uart_dev_s *dev)
{
  struct bk7258_uart_s *priv = dev->priv;
  bk_err_t flow_result = BK_OK;

  if (priv->id == UART_ID_0)
    {
      flow_result = priv->flow_control ?
        bk_uart_set_hw_flow_ctrl(priv->id,
                                BK7258_UART0_FLOW_THRESHOLD) :
        bk_uart_disable_hw_flow_ctrl(priv->id);
    }

  if (bk_uart_set_baud_rate(priv->id, priv->baud) != BK_OK ||
      bk_uart_set_data_bits(priv->id,
                            bk7258_uart_data_bits(priv->data_bits)) != BK_OK ||
      bk_uart_set_parity(priv->id,
                         bk7258_uart_parity(priv->parity)) != BK_OK ||
      bk_uart_set_stop_bits(priv->id,
                            bk7258_uart_stop_bits(priv->stop_bits)) != BK_OK ||
      flow_result != BK_OK)
    {
      return -EIO;
    }

#ifdef BK7258_HAVE_UART_CONSOLE
  if (bk7258_uart_is_console(dev))
    {
      if (bk7258_lowputc_set_format(priv->baud, priv->data_bits,
                                    priv->parity, priv->stop_bits) < 0)
        {
          return -EINVAL;
        }

      bk7258_lowputc_restore_console();
    }
#endif

  return OK;
}

static void bk7258_uart_rollback_setup(struct uart_dev_s *dev)
{
  struct bk7258_uart_s *priv = dev->priv;

  /* The SDK deinitializer releases the UART clock/FIFO state but does not
   * unmap its GPIOs.  Tuya performs that GPIO cleanup explicitly.  Remove
   * every route this wrapper may have established so a failed setup cannot
   * retain pin ownership (especially the alternate UART2 route). */

  (void)bk_uart_deinit(priv->id);

  if (priv->id == UART_ID_0)
    {
      (void)gpio_dev_unmap(GPIO_11);
      (void)gpio_dev_unmap(GPIO_10);
#ifdef CONFIG_BK7258_UART0_FLOW_CONTROL
      (void)gpio_dev_unmap(GPIO_12);
      (void)gpio_dev_unmap(GPIO_13);
#endif
    }
  else if (priv->id == UART_ID_1)
    {
      (void)gpio_dev_unmap(GPIO_0);
      (void)gpio_dev_unmap(GPIO_1);
    }
  else if (priv->id == UART_ID_2)
    {
      (void)gpio_dev_unmap(GPIO_31);
      (void)gpio_dev_unmap(GPIO_30);
#ifdef CONFIG_BK7258_UART2_PINS_P40_P41
      (void)gpio_dev_unmap(GPIO_41);
      (void)gpio_dev_unmap(GPIO_40);
#endif
    }

#ifdef BK7258_HAVE_UART_CONSOLE
  if (bk7258_uart_is_console(dev))
    {
      /* Keep the polled console usable after the SDK ownership handoff is
       * rolled back. */

      bk7258_lowputc_restore_console();
    }
#endif
}

static void bk7258_uart_sdk_isr(uart_id_t id, void *param)
{
  struct uart_dev_s *dev = param;

  (void)id;
  uart_recvchars(dev);
}

static int bk7258_uart_setup(struct uart_dev_s *dev)
{
  struct bk7258_uart_s *priv = dev->priv;
  uart_config_t config;
  bk_err_t result;
  int ret;

  if (priv->initialized)
    {
      return OK;
    }

  ret = bk7258_uart_driver_initialize();
  if (ret < 0)
    {
      return ret;
    }

  config.baud_rate = priv->baud;
  config.data_bits = bk7258_uart_data_bits(priv->data_bits);
  config.parity = bk7258_uart_parity(priv->parity);
  config.stop_bits = bk7258_uart_stop_bits(priv->stop_bits);
  config.flow_ctrl = priv->flow_control ? UART_FLOWCTRL_CTS_RTS :
                                          UART_FLOWCTRL_DISABLE;
  config.src_clk = UART_SCLK_XTAL_26M;
  config.rx_dma_en = UART_DMA_DISABLE;
  config.tx_dma_en = UART_DMA_DISABLE;

#ifdef BK7258_HAVE_UART_CONSOLE
  if (bk7258_uart_is_console(dev))
    {
      bk7258_lowputc_handoff(true);
    }
#endif

  result = bk_uart_init(priv->id, &config);

#ifdef BK7258_HAVE_UART_CONSOLE
  if (bk7258_uart_is_console(dev))
    {
      bk7258_lowputc_handoff(false);
    }
#endif

  if (result != BK_OK)
    {
      return -EIO;
    }

  ret = bk7258_uart_apply_pin_route(priv);
  if (ret < 0)
    {
      goto fail;
    }

  ret = bk7258_uart_apply_format(dev);
  if (ret < 0)
    {
      goto fail;
    }

  if (bk_uart_disable_sw_fifo(priv->id) != BK_OK ||
      bk_uart_set_rx_full_threshold(priv->id, 1) != BK_OK)
    {
      ret = -EIO;
      goto fail;
    }

  priv->rxbyte = -1;
  priv->initialized = true;
  return OK;

fail:
  bk7258_uart_rollback_setup(dev);
  return ret;
}

static void bk7258_uart_shutdown(struct uart_dev_s *dev)
{
  /* Device ownership is static for the firmware lifetime. */

  (void)dev;
}

static int bk7258_uart_attach(struct uart_dev_s *dev)
{
  struct bk7258_uart_s *priv = dev->priv;
  bk_err_t ret;

  ret = bk_uart_register_rx_isr(priv->id, bk7258_uart_sdk_isr, dev);
  return ret == BK_OK ? OK : -EIO;
}

static void bk7258_uart_detach(struct uart_dev_s *dev)
{
  struct bk7258_uart_s *priv = dev->priv;

  (void)bk_uart_disable_rx_interrupt(priv->id);
  (void)bk_uart_register_rx_isr(priv->id, NULL, NULL);
  priv->rx_enabled = false;
}

#ifdef CONFIG_SERIAL_TERMIOS
static int bk7258_uart_termios_get(struct bk7258_uart_s *priv,
                                   struct termios *termiosp)
{
  if (termiosp == NULL)
    {
      return -EINVAL;
    }

  termiosp->c_cflag = 0;
  switch (priv->data_bits)
    {
      case 5:
        termiosp->c_cflag |= CS5;
        break;
      case 6:
        termiosp->c_cflag |= CS6;
        break;
      case 7:
        termiosp->c_cflag |= CS7;
        break;
      default:
        termiosp->c_cflag |= CS8;
        break;
    }

  if (priv->parity != 0u)
    {
      termiosp->c_cflag |= PARENB;
      if (priv->parity == 1u)
        {
          termiosp->c_cflag |= PARODD;
        }
    }

  if (priv->stop_bits == 2u)
    {
      termiosp->c_cflag |= CSTOPB;
    }

#if defined(CONFIG_SERIAL_IFLOWCONTROL) && \
    defined(CONFIG_SERIAL_OFLOWCONTROL)
  if (priv->flow_control)
    {
      termiosp->c_cflag |= CRTS_IFLOW | CCTS_OFLOW;
    }
#endif

  cfsetispeed(termiosp, priv->baud);
  cfsetospeed(termiosp, priv->baud);
  return OK;
}

static int bk7258_uart_termios_set(struct uart_dev_s *dev,
                                   const struct termios *termiosp)
{
  struct bk7258_uart_s *priv = dev->priv;
  uint32_t baud;
  uint8_t data_bits;
  uint8_t parity;
  uint8_t stop_bits;
  bool flow_control = false;
  bool rx_enabled;
  unsigned int count;

  if (termiosp == NULL)
    {
      return -EINVAL;
    }

  baud = cfgetispeed(termiosp);
  if (baud < 400u || baud > 5200000u)
    {
      return -EINVAL;
    }

  switch (termiosp->c_cflag & CSIZE)
    {
      case CS5:
        data_bits = 5u;
        break;
      case CS6:
        data_bits = 6u;
        break;
      case CS7:
        data_bits = 7u;
        break;
      case CS8:
        data_bits = 8u;
        break;
      default:
        return -EINVAL;
    }

  parity = (termiosp->c_cflag & PARENB) == 0 ? 0u :
           ((termiosp->c_cflag & PARODD) != 0 ? 1u : 2u);
  stop_bits = (termiosp->c_cflag & CSTOPB) != 0 ? 2u : 1u;

#if defined(CONFIG_SERIAL_IFLOWCONTROL) && \
    defined(CONFIG_SERIAL_OFLOWCONTROL)
  if ((termiosp->c_cflag & (CRTS_IFLOW | CCTS_OFLOW)) != 0)
    {
      if ((termiosp->c_cflag & (CRTS_IFLOW | CCTS_OFLOW)) !=
          (CRTS_IFLOW | CCTS_OFLOW) || priv->id != UART_ID_0)
        {
          return -EINVAL;
        }

      flow_control = true;
    }
#else
  flow_control = priv->flow_control;
#endif

  /* v3.1.1.9 has no runtime flow-control setter.  Refuse a partial hardware
   * transition; baud/data/parity/stop changes remain fully supported.
   */

  if (flow_control != priv->flow_control)
    {
      return -ENOTSUP;
    }

  for (count = 0; count < BK7258_UART_TX_POLL_LIMIT; count++)
    {
      if (bk_uart_is_tx_over(priv->id))
        {
          break;
        }
    }

  if (count == BK7258_UART_TX_POLL_LIMIT)
    {
      return -EBUSY;
    }

  rx_enabled = priv->rx_enabled;
  (void)bk_uart_disable_rx_interrupt(priv->id);
  priv->baud = baud;
  priv->data_bits = data_bits;
  priv->parity = parity;
  priv->stop_bits = stop_bits;

  if (bk7258_uart_apply_format(dev) < 0)
    {
      return -EIO;
    }

  if (rx_enabled)
    {
      (void)bk_uart_enable_rx_interrupt(priv->id);
    }

  return OK;
}
#endif

static int bk7258_uart_ioctl(struct file *filep, int cmd,
                             unsigned long arg)
{
  struct inode *inode = filep->f_inode;
  struct uart_dev_s *dev = inode->i_private;
  struct bk7258_uart_s *priv = dev->priv;

#ifdef CONFIG_SERIAL_TERMIOS
  switch (cmd)
    {
      case TCGETS:
        return bk7258_uart_termios_get(priv, (struct termios *)arg);
      case TCSETS:
        return bk7258_uart_termios_set(dev,
                                       (const struct termios *)arg);
      default:
        break;
    }
#else
  (void)priv;
  (void)cmd;
  (void)arg;
#endif

  return -ENOTTY;
}

static bool bk7258_uart_rxavailable(struct uart_dev_s *dev)
{
  struct bk7258_uart_s *priv = dev->priv;

  if (priv->rxbyte < 0)
    {
      uint8_t byte;
      int nread = bk_uart_read_bytes(priv->id, &byte, 1, 0);

      priv->rxbyte = nread == 1 ? byte : -1;
    }

  return priv->rxbyte >= 0;
}

static int bk7258_uart_receive(struct uart_dev_s *dev, unsigned int *status)
{
  struct bk7258_uart_s *priv = dev->priv;
  int ch = priv->rxbyte;

  priv->rxbyte = -1;
  if (status != NULL)
    {
      *status = 0;
    }

  return ch;
}

static void bk7258_uart_rxint(struct uart_dev_s *dev, bool enable)
{
  struct bk7258_uart_s *priv = dev->priv;

  if (enable)
    {
      priv->rx_enabled = bk_uart_enable_rx_interrupt(priv->id) == BK_OK;
    }
  else
    {
      (void)bk_uart_disable_rx_interrupt(priv->id);
      priv->rx_enabled = false;
    }
}

static void bk7258_uart_send(struct uart_dev_s *dev, int ch)
{
  struct bk7258_uart_s *priv = dev->priv;
  uint8_t byte = (uint8_t)ch;

#ifdef BK7258_HAVE_UART_CONSOLE
  if (bk7258_uart_is_console(dev))
    {
      bk7258_lowputc_ensure_console();
    }
#endif

  (void)bk_uart_write_bytes(priv->id, &byte, 1);
}

static void bk7258_uart_txint(struct uart_dev_s *dev, bool enable)
{
  if (enable)
    {
      uart_xmitchars(dev);
    }
}

static bool bk7258_uart_txready(struct uart_dev_s *dev)
{
  (void)dev;
  return true;
}

static bool bk7258_uart_txempty(struct uart_dev_s *dev)
{
  struct bk7258_uart_s *priv = dev->priv;

  return bk_uart_is_tx_over(priv->id);
}

static const struct uart_ops_s g_bk7258_uart_ops =
{
  .setup       = bk7258_uart_setup,
  .shutdown    = bk7258_uart_shutdown,
  .attach      = bk7258_uart_attach,
  .detach      = bk7258_uart_detach,
  .ioctl       = bk7258_uart_ioctl,
  .receive     = bk7258_uart_receive,
  .rxint       = bk7258_uart_rxint,
  .rxavailable = bk7258_uart_rxavailable,
  .send        = bk7258_uart_send,
  .txint       = bk7258_uart_txint,
  .txready     = bk7258_uart_txready,
  .txempty     = bk7258_uart_txempty,
};

#ifdef BK7258_HAVE_UART_CONSOLE
void bk7258_uart_recover_console(void)
{
  struct bk7258_uart_s *priv = CONSOLE_DEV.priv;

  if (!priv->initialized)
    {
      return;
    }

  (void)bk_uart_disable_rx_interrupt(priv->id);
  (void)bk7258_uart_apply_pin_route(priv);
  (void)bk7258_uart_apply_format(&CONSOLE_DEV);
  (void)bk_uart_disable_sw_fifo(priv->id);
  (void)bk_uart_set_rx_full_threshold(priv->id, 1);
  (void)bk_uart_register_rx_isr(priv->id, bk7258_uart_sdk_isr,
                                &CONSOLE_DEV);
  if (priv->rx_enabled)
    {
      (void)bk_uart_enable_rx_interrupt(priv->id);
    }

  priv->rxbyte = -1;
}
#endif

static int bk7258_uart_pm_prepare_one(struct bk7258_uart_s *priv)
{
  unsigned int count;

  if (!priv->initialized)
    {
      return OK;
    }

  for (count = 0; count < BK7258_UART_TX_POLL_LIMIT; count++)
    {
      if (bk_uart_is_tx_over(priv->id))
        {
          return OK;
        }
    }

  return -EBUSY;
}

int bk7258_uart_pm_prepare(void)
{
  int ret;

#ifdef CONFIG_BK7258_UART0
  ret = bk7258_uart_pm_prepare_one(&g_bk7258_uart0priv);
  if (ret < 0)
    {
      return ret;
    }
#endif
#ifdef CONFIG_BK7258_UART1
  ret = bk7258_uart_pm_prepare_one(&g_bk7258_uart1priv);
  if (ret < 0)
    {
      return ret;
    }
#endif
#ifdef CONFIG_BK7258_UART2
  ret = bk7258_uart_pm_prepare_one(&g_bk7258_uart2priv);
  if (ret < 0)
    {
      return ret;
    }
#endif

  return OK;
}

static void bk7258_uart_pm_restore_one(struct uart_dev_s *dev)
{
  struct bk7258_uart_s *priv = dev->priv;

  if (!priv->initialized)
    {
      return;
    }

  (void)bk7258_uart_apply_pin_route(priv);
  (void)bk7258_uart_apply_format(dev);
  (void)bk_uart_disable_sw_fifo(priv->id);
  (void)bk_uart_set_rx_full_threshold(priv->id, 1);
  (void)bk_uart_register_rx_isr(priv->id, bk7258_uart_sdk_isr, dev);
  if (priv->rx_enabled)
    {
      (void)bk_uart_enable_rx_interrupt(priv->id);
    }
}

void bk7258_uart_pm_restore(void)
{
#ifdef CONFIG_BK7258_UART0
  bk7258_uart_pm_restore_one(&g_bk7258_uart0dev);
#endif
#ifdef CONFIG_BK7258_UART1
  bk7258_uart_pm_restore_one(&g_bk7258_uart1dev);
#endif
#ifdef CONFIG_BK7258_UART2
  bk7258_uart_pm_restore_one(&g_bk7258_uart2dev);
#endif
}

